1	#!/bin/sh
2	IN=$(cat); D="$(dirname "$0")"; printf '%s\n' "$IN" >>"$HOOK_LOG"
3	EV=$(printf '%s' "$IN" | sed -n 's/.*"hook_event_name":"\([A-Za-z]*\)".*/\1/p')
4	case "$EV" in
5	 SessionStart) echo '{"hookSpecificOutput":{"hookEventName":"SessionStart","additionalContext":"SS-CTX"}}';;
6	 PostToolUse) echo '{"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"POST-CTX"}}';;
7	 SubagentStart) echo "SAS-STDERR" >&2;;
8	 SubagentStop) M=$(cat "$D/sstopn" 2>/dev/null || echo 0); M=$((M+1)); echo $M > "$D/sstopn"; if [ $M = 1 ]; then echo "SUB-BLOCK" >&2; exit 2; fi; echo "SAST-STDERR" >&2;;
9	esac
10	exit 0
